def ztest(F,S,n=120):
    k=S.shape[1]; t=np.trace(S.T@F@S)
    nl=[];nr=[]
    for i in range(n):
        R=rng.standard_normal((640,k)); R[~keep]=0; R=np.linalg.qr(R)[0]
        nl.append(np.trace(S.T@F@R)); nr.append(np.trace(R.T@F@S))
    return t/np.sqrt((np.var(nl)+np.var(nr))/2)
